export function hasTechIcon(name: string): boolean {
  if (!name) return false;
  const key = name.toLowerCase().replace(/[^a-z0-9]/g, '');
  return Boolean(TECH_ICONS[name.toLowerCase()] || TECH_ICONS[key]);
}

export function getTechIconDef(name: string): TechIconDef | undefined {
  if (!name) return undefined;
  const key = name.toLowerCase().replace(/[^a-z0-9]/g, '');
  return TECH_ICONS[name.toLowerCase()] || TECH_ICONS[key];
}

export interface TechIconProps {
  name: string;
  className?: string;
  color?: string;
  size?: number;
}

function TechIconComponent({ name, className = 'size-4', color, size }: TechIconProps) {
  const icon = getTechIconDef(name);
  if (!icon) return null;

  return (
    <svg
      role="img"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      className={className}
      fill={color || ('#' + icon.hex)}
      aria-label={icon.title}
    >
      <path d={icon.path} />
    </svg>
  );
}

export const TechIcon = memo(TechIconComponent);
